  font-size: 28px;
  font-weight: 800;
  color: var(--color-text);
}

.subtitle {
  font-size: 15px;
  color: var(--color-text-secondary);
}

.content {
  padding: 0 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.button {
  background: var(--color-accent);
  border-radius: 12px;
  padding: 16px;
  align-items: center;
  justify-content: center;
  display: flex;
}

.button__text {
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
}

.button--secondary {
  background: var(--color-card);
  border: 1px solid var(--color-accent);
}

.button--secondary .button__text {
  color: var(--color-accent);
}

.button--disabled {
  background: var(--color-disabled-bg);
  border: 1px solid var(--color-disabled-bg);
}

.button--disabled .button__text {
  color: var(--color-disabled-text);
}

.status-line {
  font-size: 15px;
  color: var(--color-text-secondary);
  padding: 4px 2px;
}

.section-header {
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--color-text-secondary);
  padding: 12px 2px 4px;
}

.card {
  background: var(--color-card);
  border-radius: 12px;
  padding: 4px 12px;
}

.empty-state {
  color: var(--color-text-secondary);
  font-size: 14px;
  text-align: center;
  padding: 28px 12px;
}

.list-row {
  display: flex;
  align-items: center;
  padding: 12px 8px;
  border-bottom: 1px solid var(--color-border);
}

.list-row:last-child {
  border-bottom: none;
}

.list-row--today {
  background: var(--color-today-bg);
  border-radius: 8px;
}

.list-row__text {
  font-size: 15px;
  color: var(--color-text);
}

.transcript {
  background: var(--color-card);
  border-radius: 12px;
  padding: 16px;
  min-height: 140px;
}

.transcript__text {
  font-size: 15px;
  line-height: 21px;
  color: var(--color-text);
}

